document.addEventListener("DOMContentLoaded",function(){const c=document.querySelectorAll("video.lazy-video");if("IntersectionObserver"in window){const s=new IntersectionObserver(function(o,r){o.forEach(function(a){if(a.isIntersecting){const e=a.target;if(e.dataset.src&&(e.src=e.dataset.src),e.querySelectorAll("source").forEach(t=>{t.dataset.src&&(t.src=t.dataset.src)}),e.load(),e.hasAttribute("autoplay")){const t=e.play();t!==void 0&&t.catch(n=>{console.log("Autoplay prevented or video not ready:",n)})}e.classList.remove("lazy-video"),r.unobserve(e)}})});c.forEach(function(o){s.observe(o)})}else c.forEach(function(s){s.dataset.src&&(s.src=s.dataset.src),s.querySelectorAll("source").forEach(r=>{r.dataset.src&&(r.src=r.dataset.src)}),s.load()})});
